// Changes: Check a dynamic range step and emit its direction.
static IrOperand lower_step_direction(Ctx* ctx,
                                      IrFunctionId function_id,
                                      IrBlockId* block_id,
                                      IrOperand step) {
  // Semantic analysis rejects literal zero steps.
  if (step.type == IR_OP_INT32)
    return bool_operand(step.value.int32_value > 0);

  IrOperand zero = int_operand(0);
  IrOperand is_zero =
      add_binary(ctx, function_id, *block_id, IR_INST_EQ, IR_BOOL, step, zero);

  IrBlockId invalid = ir_add_block(ctx, function_id);
  IrBlockId valid = ir_add_block(ctx, function_id);
  emit_branch(ctx, function_id, *block_id, is_zero, invalid, valid);

  ir_set_terminator(ctx, function_id, invalid,
                    (IrBlockTerminator){.type = IR_TERMINATOR_EXIT,
                                        .value.exit_code = int_operand(40)});

  *block_id = valid;
  return add_binary(ctx, function_id, valid, IR_INST_GT, IR_BOOL, step, zero);
}

