// Changes: Choose the inclusive or exclusive comparison for each range
// direction.
static void emit_range_test(Ctx* ctx,
                            IrFunctionId function_id,
                            IrBlockId head,
                            IrBlockId body,
                            IrBlockId exit,
                            IrOperand current,
                            IrOperand end,
                            IrOperand ascending,
                            bool inclusive) {
  IrInstructionType up = inclusive ? IR_INST_LE : IR_INST_LT;
  IrInstructionType down = inclusive ? IR_INST_GE : IR_INST_GT;

  // A constant direction needs only one comparison in the loop header.
  if (ascending.type == IR_OP_BOOL) {
    IrInstructionType comparison = ascending.value.bool_value ? up : down;
    IrOperand in_range =
        add_binary(ctx, function_id, head, comparison, IR_BOOL, current, end);
    emit_branch(ctx, function_id, head, in_range, body, exit);
    return;
  }

  IrBlockId up_block = ir_add_block(ctx, function_id);
  IrBlockId down_block = ir_add_block(ctx, function_id);
  emit_branch(ctx, function_id, head, ascending, up_block, down_block);

  IrOperand up_valid =
      add_binary(ctx, function_id, up_block, up, IR_BOOL, current, end);
  emit_branch(ctx, function_id, up_block, up_valid, body, exit);

  IrOperand down_valid =
      add_binary(ctx, function_id, down_block, down, IR_BOOL, current, end);
  emit_branch(ctx, function_id, down_block, down_valid, body, exit);
}

