// Changes: Evaluate each guard in order and skip iteration work on failure.
static void lower_guards(Ctx* ctx,
                         IrFunctionId function_id,
                         IrBlockId* block_id,
                         IrBlockId advance,
                         AstNode* node) {
  size_t count = ast_node_get_child_count(node);
  for (size_t i = AST_FOR_FIRST_GUARD; i < count; i++) {
    AstNode* guard_node = ast_node_child(ctx, node, i);
    IrOperand guard = lower_expression(ctx, function_id, block_id, guard_node);
    if (*block_id == IR_INVALID_ID)
      return;

    IrBlockId next = ir_add_block(ctx, function_id);
    emit_branch(ctx, function_id, *block_id, guard, next, advance);
    *block_id = next;
  }
}

