// Changes: Add lower_for_list and dispatch non-range for-loop sources to it in lower_for.
static IrOperand lower_for_list(Ctx* ctx,
                                IrFunctionId function_id,
                                IrBlockId* block_id,
                                AstNode* node,
                                AstNode* source) {
  IrOperand list_val = lower_expression(ctx, function_id, block_id, source);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrValueId len_id = ir_add_instruction(
      ctx, function_id, *block_id,
      (IrInstruction){.type = IR_INST_CALL,
                      .result_type = IR_INT,
                      .operands.call = {.type = IR_FX_LIST_LEN,
                                        .id = IR_INVALID_ID,
                                        .args = &list_val,
                                        .arg_count = 1}});
  IrOperand len =
      len_id == IR_INVALID_ID ? int_operand(0) : value_operand(len_id);

  IrStackSlotId idx_slot = ir_add_slot(ctx, function_id, "$for_idx", IR_INT);
  emit_store(ctx, function_id, *block_id, idx_slot, int_operand(0));

  IrBlockId head = ir_add_block(ctx, function_id);
  IrBlockId body = ir_add_block(ctx, function_id);
  IrBlockId advance = ir_add_block(ctx, function_id);
  IrBlockId exit = ir_add_block(ctx, function_id);
  emit_jump(ctx, function_id, *block_id, head);

  IrOperand idx = emit_load(ctx, function_id, head, idx_slot, IR_INT);
  IrOperand in_bounds =
      add_binary(ctx, function_id, head, IR_INST_LT, IR_BOOL, idx, len);
  emit_branch(ctx, function_id, head, in_bounds, body, exit);

  AstNode* ident = ast_node_child(ctx, node, AST_FOR_IDENT);
  const SymtableData* symbol = ast_node_get_symbol(ident);
  IrOperand get_args[2] = {list_val, idx};
  IrValueId elem_id = ir_add_instruction(
      ctx, function_id, body,
      (IrInstruction){.type = IR_INST_CALL,
                      .result_type = symbol->ir_type,
                      .operands.call = {.type = IR_FX_LIST_GET,
                                        .id = IR_INVALID_ID,
                                        .args = get_args,
                                        .arg_count = 2}});
  IrOperand elem =
      elem_id == IR_INVALID_ID ? unit_operand() : value_operand(elem_id);
  emit_store(ctx, function_id, body, symbol->ir_index, elem);

  lower_guards(ctx, function_id, &body, advance, node);
  if (body != IR_INVALID_ID) {
    AstNode* body_node = ast_node_child(ctx, node, AST_FOR_BODY);
    lower_statement(ctx, function_id, &body, body_node);

    if (body != IR_INVALID_ID)
      emit_jump(ctx, function_id, body, advance);
  }

  IrOperand next_idx = add_binary(ctx, function_id, advance, IR_INST_ADD,
                                  IR_INT, idx, int_operand(1));
  emit_store(ctx, function_id, advance, idx_slot, next_idx);
  emit_jump(ctx, function_id, advance, head);

  *block_id = exit;
  return unit_operand();
}

