// Changes: Lower range setup, bounds, guards, body, and increment.
IrOperand lower_for(Ctx* ctx,
                    IrFunctionId function_id,
                    IrBlockId* block_id,
                    AstNode* node) {
  // Read the range expressions in their source order.
  AstNode* range = ast_node_child(ctx, node, AST_FOR_SOURCE);
  AstNodeType source_kind = ast_node_get_type(range);
  if (source_kind != AST_NODE_RANGE_TO && source_kind != AST_NODE_RANGE_UNTIL)
    return lower_for_list(ctx, function_id, block_id, node, range);
  AstNode* start_node = ast_node_child(ctx, range, 0);
  AstNode* end_node = ast_node_child(ctx, range, 1);
  AstNode* step_node = ast_node_child(ctx, range, AST_RANGE_STEP);

  // Evaluate the bounds and step once, before assigning the loop variable.
  IrOperand start = lower_expression(ctx, function_id, block_id, start_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrOperand end = lower_expression(ctx, function_id, block_id, end_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  // A range without an explicit step advances by one.
  IrOperand step = int_operand(1);
  if (ast_node_get_type(step_node) != AST_NODE_NONE)
    step = lower_expression(ctx, function_id, block_id, step_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  // Check the step before entering the loop, even if the range is empty.
  IrOperand ascending = lower_step_direction(ctx, function_id, block_id, step);

  // Use the slot that the guards and body reference as the loop variable.
  AstNode* ident = ast_node_child(ctx, node, AST_FOR_IDENT);
  IrStackSlotId slot = ast_node_get_symbol(ident)->ir_index;
  emit_store(ctx, function_id, *block_id, slot, start);

  // The header checks the current value before each iteration.
  IrBlockId head = ir_add_block(ctx, function_id);
  IrBlockId body = ir_add_block(ctx, function_id);
  IrBlockId advance = ir_add_block(ctx, function_id);
  IrBlockId exit = ir_add_block(ctx, function_id);
  emit_jump(ctx, function_id, *block_id, head);

  IrOperand current = emit_load(ctx, function_id, head, slot, IR_INT);
  bool inclusive = ast_node_get_type(range) == AST_NODE_RANGE_TO;
  emit_range_test(ctx, function_id, head, body, exit, current, end, ascending,
                  inclusive);

  // A failed guard jumps straight to the increment. Only paths that pass
  // every guard enter the body.
  lower_guards(ctx, function_id, &body, advance, node);
  if (body != IR_INVALID_ID) {
    AstNode* body_node = ast_node_child(ctx, node, AST_FOR_BODY);
    lower_statement(ctx, function_id, &body, body_node);

    // A return inside the body terminates that path before the increment.
    if (body != IR_INVALID_ID)
      emit_jump(ctx, function_id, body, advance);
  }

  // Both a completed body and a failed guard advance the iterator.
  IrOperand next =
      add_binary(ctx, function_id, advance, IR_INST_ADD, IR_INT, current, step);
  emit_store(ctx, function_id, advance, slot, next);
  emit_jump(ctx, function_id, advance, head);

  // Continue after the loop when the current value fails the range test.
  *block_id = exit;
  return unit_operand();
}
